create function dokument_status_seit() returns trigger language plpgsql as $$
begin
    if tg_op = 'INSERT' then
        new.status_seit := coalesce(new.status_seit, clock_timestamp());
    elsif new.status is distinct from old.status then
        new.status_seit := clock_timestamp();
    end if;
    return new;
end
$$;

create trigger dokument_status_seit before insert or update of status on dokument
    for each row execute function dokument_status_seit();
update dokument set status_seit = geaendert where status_seit is null;
create index dokument_status_seit_idx on dokument (status_seit)
    where status in ('VERARBEITUNG', 'FEHLER', 'ARCHIVIERUNG_FEHLER');
create table alarm (
    schluessel text primary key,
    erstmals timestamptz not null default clock_timestamp(),
    gemeldet timestamptz,
    erledigt timestamptz,
    constraint alarm_schluessel_ck check (schluessel ~ '^[a-z]+:[A-Za-z0-9-]+:[A-Z_]+$')
);
